    static void storeBackground(Context context,String command,String reply,boolean privateReply){storeBackground(context,command,reply,privateReply,null);}
    static void storeBackground(Context context,String command,String reply,boolean privateReply,String target){
        if(privateReply)return;
        try{android.content.SharedPreferences prefs=context.getSharedPreferences("mobile_chats",0);JSONObject store=new JSONObject(prefs.getString("data","{}"));JSONArray chats=store.optJSONArray("chats");if(chats==null)return;String selected=target==null?store.optString("active"):target;for(int i=0;i<chats.length();i++){JSONObject chat=chats.getJSONObject(i);if(!chat.optString("id").equals(selected))continue;JSONArray messages=chat.getJSONArray("messages");if(messages.length()==0||!messages.getJSONObject(messages.length()-1).optString("text").equals(command))messages.put(new JSONObject().put("role","user").put("text",command));messages.put(new JSONObject().put("role","assistant").put("text",reply));while(messages.length()>40)messages.remove(0);if(chat.optString("title").equals("Nuevo chat"))chat.put("title",command.substring(0,Math.min(50,command.length())));prefs.edit().putString("data",store.toString()).commit();break;}}catch(Exception ignored){}
    }
