        scroll=new ScrollView(this);scroll.setFillViewport(true);transcript=new LinearLayout(this);transcript.setOrientation(LinearLayout.VERTICAL);scroll.addView(transcript);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout composer=new LinearLayout(this);composer.setGravity(Gravity.BOTTOM);composer.setPadding(dp(10),dp(4),dp(6),dp(4));composer.setBackground(panel(0xff101f2b,0xff284652,20));input=new EditText(this);input.setHint("Habla conmigo o escribe…");input.setBackgroundTintList(android.content.res.ColorStateList.valueOf(Color.TRANSPARENT));input.setTextColor(Color.WHITE);input.setHintTextColor(0xff8da6b6);input.setTextSize(16);input.setMaxLines(4);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(4000)});composer.addView(input,new LinearLayout.LayoutParams(0,-2,1));Button mic=button("Mic");mic.setContentDescription("Dictar una pregunta");mic.setOnClickListener(v->dictate());composer.addView(mic,new LinearLayout.LayoutParams(dp(52),dp(50)));send=button("↑");send.setContentDescription("Enviar");send.setOnClickListener(v->submit());composer.addView(send,new LinearLayout.LayoutParams(dp(46),dp(50)));root.addView(composer);setContentView(root);
