        String[] examples={"¿Qué día es hoy?","Lee mis notificaciones","Mis recordatorios","Recuérdame ","Abre ","Pon música de ","Busca en Google ","Noticias de hoy","Ayuda"};
        input.setText(examples[index]);input.setSelection(input.length());input.requestFocus();
